"""Export existing immutable inputs into a new boot-bound Host-DAX service bundle.

No SDK, root, service, mount, permission or Guest operations. No lower payload
copy or hardlink: a later root launcher must bind the source layer directory
read-only inside its private mount namespace. An exported template is not ready.
"""
import base64
import hashlib
import json
import os
from pathlib import Path
import platform
import re
import stat
import zlib

ROOT=Path('/home/jwk/agent')
CORE='5723411cfe6066a2d5a9cbe8e796298da0f40b5e'
TEMPLATE='01a15c9e-54d0-7b92-a50b-0b6ec2e9136b'
CATALOG_SHA='9e9a097bf18d389ba68f54b2ef194b950c445df093635e2f97475eec6f81064b'
IMAGE_SHA='68e386f9ad745c7c9a19de5dad354e175b62b5a8296a53e559468d562c8addc5'
PACKAGE=''
PACKAGE_SHA='5be86b74933644bea19e796d543719e320b5537fb49a04f6b00dfb5e1341123d'
BINS={'bin/server':'759423e634e25bc2e74067bfaccc16e40720907fc0e717269261dd573f0097df',
      'bin/aenv':'b07e0ad826a6080a4481cb42278023732f21d090edf813f5bedd4438a486e1f2',
      'bin/uvm-ublk-daemon':'5291c267777cd91c4b853c6d40720e8d87200b2a0162024782534c4126cba726',
      'deps/firecracker/1.15.1-patch-v3/firecracker':'e9588526096f45380b8debf2d41bf33a2fb26f8abea0a9bed841627327782a0b'}
PHASE='identity'
EXPORT_CREATED=False


def need(ok,reason):
    if not ok:raise RuntimeError(reason)


def read(p,limit=2*1024**2):
    need(p.resolve(strict=True)==p,'Redirected input')
    fd=os.open(p,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK|os.O_CLOEXEC)
    with os.fdopen(fd,'rb') as f:
        s=os.fstat(f.fileno())
        need(stat.S_ISREG(s.st_mode) and s.st_uid==1204 and s.st_size<=limit,'Input type/owner/size differs')
        raw=f.read(limit+1);t=os.fstat(f.fileno())
    identity=lambda x:(x.st_dev,x.st_ino,x.st_size,x.st_mtime_ns,x.st_ctime_ns)
    need(len(raw)<=limit and identity(s)==identity(t)==identity(p.stat()),'Input changed')
    return raw


def hash_file(p,limit):
    need(p.resolve(strict=True)==p,'Redirected payload')
    fd=os.open(p,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK|os.O_CLOEXEC)
    h=hashlib.sha256()
    with os.fdopen(fd,'rb') as f:
        s=os.fstat(f.fileno())
        need(stat.S_ISREG(s.st_mode) and s.st_uid==1204 and s.st_size<=limit,'Payload type/owner/size differs')
        for data in iter(lambda:f.read(1024**2),b''):h.update(data)
        t=os.fstat(f.fileno())
    identity=lambda x:(x.st_dev,x.st_ino,x.st_size,x.st_mtime_ns,x.st_ctime_ns)
    need(identity(s)==identity(t)==identity(p.stat()),'Payload changed')
    return {'path':str(p),'bytes':s.st_size,'sha256':h.hexdigest(),
            'identity':list(identity(s)),'fullHash':True}


def folder(p):
    need(p.resolve()==p and not p.exists(),'Existing/redirected export preserved')
    p.mkdir(mode=0o700)


def put(p,raw):
    need(p.parent.resolve()==p.parent,'Redirected output parent')
    fd=os.open(p,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)
    with os.fdopen(fd,'wb') as f:f.write(raw);f.flush();os.fsync(f.fileno())


def encoded(v):return (json.dumps(v,sort_keys=True,separators=(',',':'))+'\n').encode()


def unpack():
    d=zlib.decompressobj();raw=d.decompress(base64.b64decode(PACKAGE,validate=True),1024**2+1)
    need(len(raw)<=1024**2 and d.eof and not d.unused_data and not d.unconsumed_tail,'Provider expansion differs')
    need(hashlib.sha256(raw).hexdigest()==PACKAGE_SHA,'Provider package differs')
    package=json.loads(raw)
    need(set(package)=={'aenv_ub_provider','tests'},'Package shape differs')
    return package


def old_objects(n):
    result=[]
    for p in (ROOT/'r'/('hpmem-'+n+'-v1')/'provider/owner.json',
              ROOT/'r'/('uf-'+n+'-v1')/'p/owner.json'):
        if not p.exists():continue
        raw=read(p);state=json.loads(raw)
        names=sorted(set(re.findall(r'\baenv_[0-9a-f]{32}\b',raw.decode())))
        need(len(names)<=32,'Too many prior object references; preserve for review')
        result.append({'journal':str(p),'sha256':hashlib.sha256(raw).hexdigest(),
                       'state':state.get('state'),'objectNames':names,
                       'meaning':'historical references only; not SDK existence or deletion proof'})
    return result


def managed_layers(committed):
    # SnapshotCommitted.rootfs_layers is Vec<OverlaybdLayerRef>, whereas
    # memory_layers is Vec<ManagedLayer>. Do not expect an enum tag on memory.
    rows=[]
    for ref in committed['rootfs_layers']:
        need(isinstance(ref,dict) and set(ref)=={'Managed'},'Unsupported rootfs layer reference')
        rows.append(('rootfs',ref['Managed']))
    for layer in committed['memory_layers']:
        rows.append(('memory',layer))
    for kind,row in rows:
        need(isinstance(row,dict) and {'digest','size'}<=set(row)<={'digest','size','uuid'} and
             re.fullmatch(r'sha256:[0-9a-f]{64}',row['digest']) is not None and
             type(row['size']) is int and row['size']>0 and
             (row.get('uuid') is None or isinstance(row['uuid'],str) and
              re.fullmatch(r'[0-9a-fA-F-]{36}',row['uuid']) is not None),'Invalid '+kind+' managed layer')
    return rows


def main():
    global PHASE,EXPORT_CREATED
    need(platform.system()=='Linux' and os.getuid()==os.geteuid()==1204 and os.getgid()==1205,'Use ordinary jwk')
    os.umask(0o077)
    spec=json.loads(Path('task-input.json').read_bytes())
    current={'hostname':platform.node(),'uid':os.getuid(),'gid':os.getgid(),'architecture':platform.machine(),
             'kernel':platform.release(),'machineId':Path('/etc/machine-id').read_text().strip(),
             'bootId':Path('/proc/sys/kernel/random/boot_id').read_text().strip()}
    need(spec['expectedIdentity']==current,'Reviewed boot identity differs')
    caps=[int(line.split()[1],16) for line in Path('/proc/self/status').read_text().splitlines()
          if line.startswith(('CapInh:','CapPrm:','CapEff:','CapAmb:'))]
    need(len(caps)==4 and not any(caps),'Zero capabilities required')
    n={'server1':'a','agent1':'b'}[platform.node()]
    work=ROOT/'r'/('hpab-'+n+'-v1')
    need(not work.exists() and not work.is_symlink(),'Prior bundle exists; no retry or overwrite')
    source=ROOT/'deployments/agentenv-direct-ub-deletefix-v1'
    PHASE='retained-binary-attestation'
    binaries={}
    for rel,pin in BINS.items():
        r=hash_file(source/rel,128*1024**2)
        need(r['sha256']==pin,'Retained binary changed: '+rel);binaries[rel]=r
    PHASE='kernel-and-tools-attestation'
    dependencies={rel:hash_file(source/rel,512*1024**2) for rel in
        ('deps/kernel/vmlinux-6.1.175/vmlinux.bin','deps/tools/0.1.1/tools.ext4')}
    repository=ROOT/'deployments/agentenv-lazy-four-32ce41c/state/snapshot-store/repository'
    PHASE='pinned-catalog-read'
    record_file=repository/'catalog/records'/(TEMPLATE+'.json');raw=read(record_file)
    need(hashlib.sha256(raw).hexdigest()==CATALOG_SHA,'T1 catalog changed')
    record=json.loads(raw);committed=record['committed']
    need(record['id']==TEMPLATE and len(committed['rootfs_layers'])==8 and len(committed['memory_layers'])==1
         and not committed.get('attached_drives') and not committed.get('volume_snapshots'),'T1 shape differs')
    files=[]
    PHASE='managed-layer-metadata'
    for kind,row in managed_layers(committed):
        digest=row['digest']
        p=repository/'managed-layers'/(digest.replace(':','_')+'.overlaybd.commit')
        need(p.resolve(strict=True)==p,'Layer redirected')
        s=p.stat();need(stat.S_ISREG(s.st_mode) and s.st_uid==1204 and s.st_size==row['size'],'Layer metadata differs')
        files.append({'kind':kind,'digest':digest,'bytes':row['size'],'source':str(p),'sha256VerifiedNow':False})
    image=None
    PHASE='retained-image-attestation'
    if n=='a':
        image=hash_file(ROOT/'r/hpd4-a-v1/rootfs-lowers.ext4',2*1024**3)
        need(image['bytes']==1811939328 and image['sha256']==IMAGE_SHA,'Prepared full image changed')
    PHASE='old-object-journals-and-provider-package'
    prior_objects=old_objects(n);package=unpack()
    # No side effects until every retained input above has been checked.
    PHASE='export-new-directory'
    folder(work);EXPORT_CREATED=True;put(work/'export-intent.json',encoded({'state':'exporting_immutable_inputs',
        'identity':current,'SDK_called':False,'servicesChanged':False}))
    folder(work/'provider-code');manifest={}
    for group in ('aenv_ub_provider','tests'):
        folder(work/'provider-code'/group)
        for name,body in package[group].items():
            need(Path(name).name==name and name.endswith('.py'),'Unexpected provider member')
            code=body.encode();put(work/'provider-code'/group/name,code)
            manifest[group+'/'+name]=hashlib.sha256(code).hexdigest()
    for rel in ('seed','seed/repository','seed/repository/catalog','seed/repository/catalog/records',
                'seed/repository/managed-layers','seed/repository/snapshots',
                'seed/repository/snapshots/'+TEMPLATE,'state','config','logs'):
        folder(work/rel)
    put(work/'seed/repository/catalog/records'/record_file.name,raw)
    metadata={}
    PHASE='snapshot-metadata-export'
    for name in ('commit','firecracker-manifest.json','vm_state.bin'):
        data=read(repository/'snapshots'/TEMPLATE/name)
        put(work/'seed/repository/snapshots'/TEMPLATE/name,data)
        metadata[name]={'bytes':len(data),'sha256':hashlib.sha256(data).hexdigest()}
    put(work/'provider-source-manifest.json',encoded(manifest))
    plan={'identity':current,'workDirectory':str(work),'coreCommit':CORE,'templateId':TEMPLATE,
        'sourceDeployment':str(source),'binaries':binaries,'dependencies':dependencies,'image':image,'layers':files,
        'snapshotMetadata':metadata,'providerPackageSha256':PACKAGE_SHA,
        'providerManifestSha256':hashlib.sha256(encoded(manifest)).hexdigest(),
        'sourceManagedLayers':str(repository/'managed-layers'),
        'privateReadonlyBindTarget':str(work/'seed/repository/managed-layers'),
        'readonlyManagedLayersBindRequired':True,'launchReady':False,
        'oldObjectsForReconciliation':prior_objects,
        'logicalUbBytes':1811939328,'maxPostMapCoverageBytes':4294967296,
        'physicalHardQuota':False,'GuestPlannedThisRound':False,'normalFileFallbackAllowed':False}
    put(work/'service-input-plan.json',encoded(plan))
    report={'status':'AB_HOST_DAX_SERVICE_INPUTS_EXPORTED_NOT_STARTED','plan':plan,
        'inputPlanSha256':hashlib.sha256(encoded(plan)).hexdigest(),
        'SDK_called':False,'Guest_created':False,'servicesChanged':False,'moduleChanged':False,
        'dataPayloadCopied':False,'dataPayloadHardlinked':False,
        'note':'source A image was fully read for attestation; this is preparation, not a cache measurement'}
    put(work/'exported.json',encoded(report))
    PHASE='completed'
    print(json.dumps(report,indent=2))


if __name__=='__main__':
    try:main()
    except Exception as error:
        print(json.dumps({'status':'AB_HOST_DAX_EXPORT_STOPPED_PRESERVE_STATE','errorType':type(error).__name__,
            'phase':PHASE,'reason':str(error) if isinstance(error,RuntimeError) else type(error).__name__,
            'exportDirectoryCreated':EXPORT_CREATED,'SDK_called':False,'servicesChanged':False}))
        raise SystemExit(1)
